<script setup lang="ts">
import { computed } from 'vue'
import { useMissionStore } from '../../stores/mission'
import { assessmentResult } from '../../utils/quality'
import Icon from '../common/AppIcon.vue'
const store = useMissionStore()
const tabs = [{ id: 'quality', label: 'Data quality' }, { id: 'events', label: 'Shot event' }, { id: 'assessment', label: 'Assessment' }, { id: 'insights', label: 'AI insights' }]
const assessment = computed(() => store.mission.assessments.find(a => a.eventId === store.selectedEventId))
</script>
<template><aside class="panel analysis-panel"><div class="panel-heading"><div class="heading-icon cyan"><Icon name="ShieldCheck"/></div><div><h2>AI analysis</h2><span class="muted small">Evidence-led verification</span></div><span class="outline-tag">LOCAL RULES</span></div><div class="analysis-tabs" role="tablist" aria-label="Analysis sections"><button v-for="t in tabs" :id="`tab-${t.id}`" :key="t.id" role="tab" :aria-selected="store.tab === t.id" :aria-controls="`analysis-${t.id}`" :class="{ active: store.tab === t.id }" @click="store.tab = t.id">{{ t.label }}</button></div>
  <div class="panel-scroll analysis-content" role="tabpanel" :id="`analysis-${store.tab}`" :aria-labelledby="`tab-${store.tab}`">
    <template v-if="store.tab === 'quality'"><div class="section-label">DATA QUALITY OVERVIEW <Icon name="CircleHelp" :size="14"/></div><div class="quality-score"><div class="score-ring" :style="{ '--score': store.report.completeness + '%' }"><div><strong>{{ store.report.completeness }}<small>%</small></strong><span>COMPLETE</span></div></div><div><span class="status-badge warning"><i></i>{{ store.report.validationStatus === 'valid' ? 'VALIDATED' : 'REVIEW REQUIRED' }}</span><p>Track coverage estimate</p><span class="small muted">{{ store.mission.telemetry.length }} position records</span></div></div><div class="metric-list"><div v-for="metric in store.report.metrics" :key="metric.label" class="quality-metric" :title="metric.detail"><div><span class="metric-status" :class="metric.status"><Icon :name="metric.status === 'valid' ? 'Check' : 'AlertTriangle'" :size="14"/></span><span>{{ metric.label }}</span><Icon name="CircleHelp" :size="12" class="muted"/></div><strong :class="metric.status === 'valid' ? 'success' : 'amber-text'">{{ metric.value }}</strong></div></div><div class="insight-callout"><Icon name="AlertTriangle" :size="18"/><div><strong>Data limitations detected</strong><p>{{ store.report.missingSamples }} estimated missing samples. First samples differ by {{ store.report.maxOffsetSeconds }}s. Review evidence before drawing conclusions.</p><button class="text-button" @click="store.tab = 'insights'">Review insights <Icon name="ArrowRight" :size="14"/></button></div></div><div class="section-label">VALIDATION METHOD</div><div class="method-card"><Icon name="ShieldCheck" :size="20"/><div><strong>Transparent, local checks</strong><p>Coordinates, timestamps, cadence and record identity. No external AI model connected.</p></div></div><p class="fine-print">Coverage is inferred within each recorded track. It does not establish completeness outside track boundaries or measurement accuracy.</p></template>
    <template v-else-if="store.tab === 'events'"><div class="section-label">SHOT EVENT RECORD</div><label class="event-select-label">Select event<select v-model="store.selectedEventId" @change="store.selectEvent(store.selectedEventId)"><option v-for="e in store.mission.events" :value="e.id" :key="e.id">{{ e.id }} · Aircraft {{ e.aircraftId }}</option></select></label><div v-if="store.selectedEvent" class="detail-list"><div><span>Aircraft ID</span><strong>{{ store.selectedEvent.aircraftId }}</strong></div><div><span>Event ID</span><strong>{{ store.selectedEvent.id }}</strong></div><div><span>Timestamp (UTC)</span><strong>{{ store.selectedEvent.timestamp }}</strong></div><div><span>Event source</span><strong>{{ store.selectedEvent.source }}</strong></div><div><span>Training profile</span><strong>{{ store.selectedEvent.weaponProfile }}</strong></div><div><span>Record validation</span><strong>{{ store.selectedEvent.validationStatus }}</strong></div><div><span>Verification status</span><strong class="amber-text">UNVERIFIED</strong></div></div><div v-else class="empty-state"><Icon name="FileText"/><p>No shot events imported</p></div><p class="fine-print">A recorded event confirms only that a source reported an event. It is not a verified HIT or MISS.</p></template>
    <template v-else-if="store.tab === 'assessment'"><div class="section-label">ASSESSMENT RESULT</div><div class="assessment-result"><Icon name="ShieldCheck" :size="38"/><strong>{{ assessmentResult(assessment) }}</strong><p>Insufficient authenticated evidence</p></div><div class="detail-list"><div><span>Event</span><strong>{{ store.selectedEventId || 'No event selected' }}</strong></div><div><span>Assessment source</span><strong>{{ assessment?.source || 'Not provided' }}</strong></div><div><span>Simulation model version</span><strong>{{ assessment?.modelVersion || 'Not provided' }}</strong></div><div><span>Evidence status</span><strong class="amber-text">No trusted simulator connection</strong></div></div><div class="insight-callout"><Icon name="AlertTriangle"/><p>HIT/MISS requires an authenticated assessment from an accredited simulator. Replay geometry and AI insights cannot establish an outcome.</p></div><p class="fine-print">Cubic ICADS integration is reserved for a future authorized adapter. Binary .rcd / .msnP5 files are not decoded.</p></template>
    <template v-else><div class="section-label">EVIDENCE & OBSERVATIONS <span>{{ store.report.insights.length }}</span></div><div v-if="!store.report.insights.length" class="empty-state">No findings. Import telemetry to perform more checks.</div><article v-for="i in store.report.insights" :key="i.id" class="insight-card"><div><span class="severity" :class="i.severity">{{ i.severity }}</span><span class="small muted">{{ i.id }}</span></div><h3>{{ i.title }}</h3><p>{{ i.reason }}</p><div class="evidence"><span>EVIDENCE</span>{{ i.evidence }}</div></article></template>
  </div><div class="panel-footer"><div class="secure-note"><Icon name="ShieldCheck" :size="14"/>Assessment outcomes are never inferred</div><button class="button full" @click="store.exportReport()"><Icon name="Download" :size="16"/>Export quality report <span class="outline-tag">JSON</span></button></div></aside></template>
